declarations.code:
template <class I, class T>

concept output_iterator =

    std::input_or_output_iterator<I> &&

    std::indirectly_writable<I, T> &&

    requires(I i, T &&t) {
        *i++ = std::forward<T>(t); /* not required to be equality-preserving */
    };

examples.code:
#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::output_iterator<int *, int>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
